L["Multiselect"] = "Selezione multipla"
L["Several choices"] = "Più scelte"
L["One setting with a value per key, drawn as a toggle each. Each row reads and writes its own key."] = "Un'impostazione con un valore per chiave, ognuno mostrato come un interruttore. Ogni riga legge e scrive la propria chiave."
L["Alpha"] = "Alfa"
L["Beta"] = "Beta"
