L["Fade Cooldown Manager"] = "Dissolvi gestore dei tempi di recupero"
L["Include Blizzard's Cooldown Manager in what Explorer Mode fades out."] = "Include il gestore dei tempi di recupero di Blizzard in ciò che la Modalità esplorazione dissolve."
L["Skin"] = "Aspetto"
L["Follow the interface theme"] = "Segui il tema dell'interfaccia"
