L["Tint color"] = "Colore della tinta"
L["The threshold, the lead and the colors are shared with nameplates. The lead and the colors are set on the Nameplates page."] = "Soglia, anticipo e colori sono condivisi con le barre dei nomi. Anticipo e colori si impostano nella pagina Barre dei nomi."

